-- public.delete_invoice
-- Generated by scripts/schema-snapshot.mjs from project heuhqqoxyggawuckxocp. Do not edit by hand.

-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.delete_invoice(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_inv record;
begin
  if not public.is_admin() then
    raise exception 'Only the team can delete an invoice.';
  end if;

  select * into v_inv from public.invoices where id = p_id;
  if v_inv is null then
    raise exception 'That invoice no longer exists.';
  end if;

  if v_inv.paid_at is not null then
    raise exception 'This invoice is marked paid, so it is the record that the money went out. Un-mark it as paid first if that was a mistake.';
  end if;

  -- The reward goes back to where it was before this invoice existed, so it
  -- can be invoiced again. Only touched if this invoice is the reason it was
  -- distributed - a reward somebody settled by hand is left alone.
  if v_inv.reward_id is not null then
    update public.rewards
       set status = 'pending',
           distributed_at = null
     where id = v_inv.reward_id
       and status = 'distributed';
  end if;

  delete from public.invoices where id = p_id;
end;
$function$;
